  gl.attachShader(p, sh(gl.FRAGMENT_SHADER, 'precision mediump float; varying vec2 v; void main(){ gl_FragColor = vec4(sin(v.x * 7.3) * 0.5 + 0.5, v.y * v.y, 0.37, 1.0); }'));
