// CSS media features read by binary search over matchMedia (not statically graded: extra readers
// of the same screen information).
function mqSearch(feature, lo, hi, step, unit) {
  // largest v in [lo, hi] (multiple of step) with (min-<feature>: v<unit>) true
  if (!matchMedia(`(min-${feature}: ${lo}${unit})`).matches) return {error: 'no match at lower bound'};
  let a = Math.round(lo / step), b = Math.round(hi / step);
  while (a < b) {
    const m = Math.ceil((a + b) / 2);
    if (matchMedia(`(min-${feature}: ${+(m * step).toFixed(4)}${unit})`).matches) a = m; else b = m - 1;
  }
  return +(a * step).toFixed(4);
}
const MQ = {
  'MediaQuery.device-width': () => mqSearch('device-width', 0, 20000, 1, 'px'),
  'MediaQuery.device-height': () => mqSearch('device-height', 0, 20000, 1, 'px'),
  'MediaQuery.resolution': () => mqSearch('resolution', 0.25, 8, 0.01, 'dppx'),
  'MediaQuery.width': () => mqSearch('width', 0, 20000, 1, 'px'),
};

// ---------------------------------------------------------------- canvas
function scene(ctx, w, h) {
  ctx.fillStyle = '#f60'; ctx.fillRect(10, 10, 100, 40);
  const g = ctx.createLinearGradient(0, 0, w, h); g.addColorStop(0, '#09f'); g.addColorStop(1, '#f09');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(150, 60, 45, 0, Math.PI * 1.7); ctx.fill();
  ctx.font = '18px sans-serif'; ctx.fillStyle = '#069'; ctx.fillText('FProots probe é中😀', 12, 90);
  ctx.font = 'italic 15px serif'; ctx.fillStyle = 'rgba(102,204,0,0.7)'; ctx.fillText('Cwm fjordbank glyphs vext quiz', 20, 115);
  ctx.globalCompositeOperation = 'multiply'; ctx.fillStyle = 'rgb(255,0,255)';
  ctx.beginPath(); ctx.arc(60, 70, 30, 0, Math.PI * 2); ctx.fill();
}
