// ---------------------------------------------------------------- audio
async function offlineRender() {
  const ctx = new OfflineAudioContext(1, 44100, 44100);
  const osc = ctx.createOscillator(); osc.type = 'triangle'; osc.frequency.value = 10000;
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -50; comp.knee.value = 40; comp.ratio.value = 12; comp.attack.value = 0; comp.release.value = 0.25;
  osc.connect(comp); comp.connect(ctx.destination); osc.start(0);
  return ctx.startRendering();
}
// The rendered buffer's samples read through no AudioBuffer method (Brave hooks getChannelData and
// copyFromChannel): played into a second offline context, an AudioWorklet sums the raw input samples.
const SUM_WORKLET = URL.createObjectURL(new Blob([`registerProcessor('sum', class extends AudioWorkletProcessor {
  constructor() { super(); this.s = 0; this.port.onmessage = () => this.port.postMessage(this.s); }
  process(inputs) { for (const ch of inputs[0] || []) for (const x of ch) this.s += Math.abs(x); return true; }
});`], {type: 'text/javascript'}));
async function workletSum(buffer) {
  const ctx = new OfflineAudioContext(1, buffer.length, buffer.sampleRate);
  await ctx.audioWorklet.addModule(SUM_WORKLET);
  const src = new AudioBufferSourceNode(ctx, {buffer}), sum = new AudioWorkletNode(ctx, 'sum');
  src.connect(sum); sum.connect(ctx.destination); src.start(0);
  await ctx.startRendering();
  return new Promise((r) => { sum.port.onmessage = (m) => r(m.data); sum.port.postMessage(0); });
}
// An analyser on the same graph, read after offline rendering.
async function analysed(read) {
  const ctx = new OfflineAudioContext(1, 44100, 44100);
  const osc = ctx.createOscillator(); osc.type = 'triangle'; osc.frequency.value = 10000;
  const an = ctx.createAnalyser(); osc.connect(an); an.connect(ctx.destination); osc.start(0);
  await ctx.startRendering();
  return read(an);
}
async function audioReads() {
  for (let i = 0; i < 2; i++) {
    put('OfflineAudioContext.startRendering', await asafe(async () => workletSum(await offlineRender())));
    put('AnalyserNode.getFloatFrequencyData', await asafe(() => analysed((an) => {
      const d = new Float32Array(an.frequencyBinCount); an.getFloatFrequencyData(d); return sha(d.buffer);
    })));
    put('AnalyserNode.getByteTimeDomainData', await asafe(() => analysed((an) => {
      const d = new Uint8Array(an.fftSize); an.getByteTimeDomainData(d); return sha(d.buffer);
    })));
    put('AudioBuffer.getChannelData', await asafe(async () => {
      const b = await offlineRender(); const d = b.getChannelData(0);
      let s = 0; for (let j = 4500; j < 5000; j++) s += Math.abs(d[j]);
      return {sum: s, sha: await sha(d.buffer.slice(0))};
    }));
    put('AudioBuffer.copyFromChannel', await asafe(async () => {
      const b = await offlineRender(); const d = new Float32Array(b.length); b.copyFromChannel(d, 0);
      return sha(d.buffer);
    }));
  }
  // On this machine the first AudioContext after a cross-site navigation sometimes waits ~20 s for
  // the output device authorization, times out and falls back to a fake 44.1 kHz device (in both
  // browsers; media/audio/audio_output_device.cc "Output device authorization timed out"). Such a
  // context reports the fallback, not the device; a construction taking >= 3 s is discarded and
  // retried (up to 4 times). Every attempt is recorded.
  let ac = null;
  const attempts = [];
  for (let i = 0; i < 4 && !ac; i++) {
    let c;
    const t = performance.now();
    try { c = new AudioContext(); } catch (e) { attempts.push(err(e)); continue; }
    const ms = Math.round(performance.now() - t);
    attempts.push({ms, sampleRate: c.sampleRate, baseLatency: c.baseLatency});
    if (ms < 3000) ac = c; else { try { await c.close(); } catch (e) {} }
  }
  put('AudioContext.construct_attempts', attempts);
  if (!ac) { for (const k of ['BaseAudioContext.sampleRate', 'AudioContext.baseLatency', 'AudioContext.outputLatency']) put(k, {error: 'no AudioContext constructed within 3 s in 4 attempts'}); return; }
  for (let i = 0; i < REPS; i++) {
    put('BaseAudioContext.sampleRate', safe(() => ac.sampleRate));
    put('AudioContext.baseLatency', safe(() => ac.baseLatency));
    await sleep(30);
  }
  put('AudioContext.state', ac.state);
  // outputLatency is 0 until the context runs; read it after a short start
  try { await Promise.race([ac.resume(), sleep(1500)]); await sleep(300); } catch (e) {}
  put('AudioContext.state', ac.state);
  for (let i = 0; i < REPS; i++) { put('AudioContext.outputLatency', safe(() => ac.outputLatency)); await sleep(30); }
  try { await ac.close(); } catch (e) {}
}

