// ---------------------------------------------------------------- trusted input
const input = {wheel: [], move: []};
addEventListener('wheel', (e) => {
  if (input.wheel.length < 6) input.wheel.push({deltaMode: e.deltaMode, deltaY: e.deltaY, deltaX: e.deltaX,
    wheelDelta: e.wheelDelta, wheelDeltaY: e.wheelDeltaY, wheelDeltaX: e.wheelDeltaX, isTrusted: e.isTrusted});
}, {passive: true});
addEventListener('mousemove', (e) => {
  if (input.move.length < 50) input.move.push({screenX: e.screenX, screenY: e.screenY, clientX: e.clientX, clientY: e.clientY,
    isTrusted: e.isTrusted});
});

// ---------------------------------------------------------------- main
async function main() {
  const t0 = performance.now();
  await sleep(300);  // let the first layout settle
  for (let i = 0; i < REPS; i++) {
    for (const [k, f] of Object.entries(SYNC)) put(k, safe(f));
    for (const [k, f] of Object.entries(MQ)) put(k, safe(f));
    await sleep(50);
  }
  await canvasReads();
  webglReads();
  await audioReads();
  await mediaCapReads();
  await otherReads();
  await screenDetailsReads();
  await seedReads();  // seeds.js
  if (WAIT_INPUT) {
    await post({run: `${RUN}.ready.${IDX}`, host: location.hostname});
    const tEnd = performance.now() + 15000;
    while (performance.now() < tEnd && (input.wheel.length < 3 || input.move.length < 1)) await sleep(100);
    if (!input.wheel.length) for (const k of ['WheelEvent.deltaMode', 'WheelEvent.wheelDelta', 'WheelEvent.deltaY', 'WheelEvent.wheelDeltaY', 'WheelEvent.wheelDeltaX']) put(k, {error: 'no wheel event arrived'});
    for (const w of input.wheel.slice(0, 3)) {
      if (!w.isTrusted) throw new Error('untrusted wheel event');
      put('WheelEvent.deltaMode', w.deltaMode); put('WheelEvent.wheelDelta', w.wheelDelta);
      put('WheelEvent.deltaY', w.deltaY); put('WheelEvent.wheelDeltaY', w.wheelDeltaY); put('WheelEvent.wheelDeltaX', w.wheelDeltaX);
    }
    if (!input.move.length) for (const k of ['MouseEvent.screenX', 'MouseEvent.screenY', 'MouseEvent.clientX', 'MouseEvent.clientY']) put(k, {error: 'no mousemove arrived'});
    for (const m of input.move.slice(-1)) {  // the last move: the pointer's final position
      put('MouseEvent.screenX', m.screenX); put('MouseEvent.screenY', m.screenY);
      put('MouseEvent.clientX', m.clientX); put('MouseEvent.clientY', m.clientY);
      put('MouseEvent.screenX-clientX', m.screenX - m.clientX); put('MouseEvent.screenY-clientY', m.screenY - m.clientY);
    }
  }
  await post({run: RUN, host: location.hostname, idx: IDX, seq: SEQ, ms: Math.round(performance.now() - t0),
              ua_brands: navigator.userAgentData ? navigator.userAgentData.brands.map((b) => b.brand) : null, readings: R});
  if (IDX + 1 < SEQ.length) {
    const q = new URLSearchParams(location.search); q.set('idx', String(IDX + 1));
    location.href = `https://${SEQ[IDX + 1]}:${location.port}${location.pathname}?${q}`;
  } else {
    document.getElementById('t').textContent = 'done';
  }
}
function startProbe() { return main(); }  // website: run on the page's button
